{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Hydroxysafflor yellow A, a polyhydroxylated glycoside, reached 1026 ng/g in rat brain after systemic administration, demonstrating that glycosidic polyphenolics can achieve meaningful CNS exposure; this transfers to the query's glycoside scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "NS1209 was detected in human CSF for up to 24 h after a single infusion with a 10 h CSF half-life, providing direct clinical evidence of sustained CNS access after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Inhibitor 6 produced a mean brain/plasma ratio of 0.69 in mice after subcutaneous infusion, indicating appreciable brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Picroside-I, a glycoside, rapidly penetrated the BBB and was detected in rat brain tissue, supporting CNS access for glycosidic natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Compound 168 rapidly crossed the BBB in rats with about 10% of the IV/IP dose entering the brain, demonstrating meaningful brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "5'-dFUrd crossed the human BBB into CSF with maximal CSF/plasma ratios of 1-3%, showing that even modest CSF partitioning can be considered meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Isovitexin, a C-glycosyl flavonoid, was detected in rat brain after IV administration, supporting brain penetration of glycosylated polyphenolics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Kanamycin, a polar aminosugar antibiotic, appeared in CSF in concentrations related to blood, indicating that aminosugar-containing molecules can access CSF.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Lorlatinib showed about 75% BBB penetration and excellent CNS exposure in humans, providing a high-penetration benchmark for CNS-active agents.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. The retrieved in vivo and clinical evidence consistently demonstrates meaningful CNS access for glycosidic, aminosugar, and heterocyclic compounds, with direct brain/CSF measurements in rats and humans. The query anthracycline glycoside shares relevant glycoside/aminosugar and polyhydroxy features, and under brain-tumor/glioma BBB disruption, adequate CNS exposure is expected.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic measurement for the exact query molecule was retrieved.",
    "Potential P-glycoprotein/BCRP efflux liability of anthracyclines is not directly quantified in the retrieved records.",
    "Tumor-associated BBB disruption is heterogeneous, so normal-brain penetration may be lower than in tumor regions."
  ],
  "new_evidence_assessment": [
